//! `__METHOD__ __path__`: takes a JSON body (generated by `engine generate
//! handler __name__`).

use axum::Json;
use axum::extract::State;
use axum::http::{HeaderMap, StatusCode};
use engine_cli::app::{Context, HandlerResult};
use engine_cli::serde_json::{Value, json};

/// `__METHOD__ __path__` with a JSON body: `202` and what was received. A
/// browser's cross-site request is refused; a handler that trusts the
/// session cookie must keep that check (or use a CSRF token).
pub async fn handle(
    State(_cx): State<Context>,
    headers: HeaderMap,
    Json(body): Json<Value>,
) -> HandlerResult<(StatusCode, Json<Value>)> {
    if !engine_cli::engine_core::serve::same_origin(&headers) {
        return Ok((StatusCode::FORBIDDEN, Json(json!({}))));
    }
    // Do the work here: `_cx.db()`, `_cx.enqueue(...)`, `_cx.session(&headers)`...
    Ok((StatusCode::ACCEPTED, Json(json!({ "received": body }))))
}
